176"] = "Gleaming Crescent Pendant", ["quest:1012"] = "Insane Druids", ["quest:1022"] = "The Howling Vale", ["quest:1035"] = "Fallen Sky Lake", ["quest:272"] = "Trial of the Sea Lion", ["quest:277"] = "Fire Taboo", ["quest:295"] = "Ormer's Revenge", ["quest:337"] = "An Old History Book", ["quest:4581"] = "Kayneth Stillwind", ["quest:5061"] = "Aquatic Form", ["quest:5645"] = "Chastise", ["quest:5673"] = "Elune's Grace", ["quest:94819"] = "Contingency Plan", ["quest:98221"] = "From the Ashes", ["quest:98246"] = "Trying Times", ["quest:98283"] = "Carnage", ["spell:18960"] = "Teleport: Moonglade", ["zone:1431"] = "Duskwood", ["zone:1437"] = "Wetlands", ["zone:1439"] = "Darkshore", ["zone:1440"] = "Ashenvale", ["zone:1450"] = "Moonglade", ["zone:1453"] = "Stormwind City", ["zone:1455"] = "Ironforge", ["zone:1457"] = "Darnassus" },
			written = { ["Cast {spell:18960}. With both half pendants in your bags, stand by the {area:2362} on the north-west shore of the lake and use a half to join them, then go to {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Cast Teleport: Moonglade. With both half pendants in your bags, stand by the Shrine of Remulos on the north-west shore of the lake and use a half to join them, then go to Dendrite Starblaze in Nighthaven. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", ["East from {npc:270637}: {npc:2093} stands beside the road."] = "East from Howin: Einar Stonegrip stands beside the road.", ["For {npc:1284} in {zone:1453}, at the end of this guide"] = "For Archbishop Benedictus in Stormwind, at the end of this guide", ["North-west from {npc:2093} to the river: Fen Creepers hide in its pools and along its banks all the way west to {area:1024}. Work west along it until you have twelve, then back east to {npc:1244}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "North-west from Einar to the river: Fen Creepers hide in its pools and along its banks all the way west to Sundown Marsh. Work west along it until you have twelve, then back east to Rethiel.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see.", ["Optional: {npc:3848} also offers {quest:1012}, three level 32 druids deep in {area:432}, a cave of quickly respawning, stealthed mobs, and back to her afterwards. It is above your level here: take it only if you are grouped or want the extra XP; the guide doesn't need it."] = "Optional: Kayneth also offers Insane Druids, three level 32 druids deep in The Dor'Danil Barrow Den, a cave of quickly respawning, stealthed mobs, and back to her afterwards. It is above your level here: take it only if you are grouped or want the extra XP; the guide doesn't need it.", ["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Take the Deeprun Tram from Tinker Town to Stormwind's Dwarven District, then walk to the Cathedral Square.", ["Tram to {zone:1453}"] = "Tram to Stormwind", ["{item:279915}, from {npc:270844} in {area:150}"] = "Nord'el, from Sylessa in Menethil Harbor", ["{npc:1078} and Whelgar"] = "Ormer and Whelgar", ["{npc:270637} camps among the Fenrunners, just west of {npc:1244}."] = "Howin Kindfeather camps among the Fenrunners, just west of Rethiel.", ["{zone:1453} flight master"] = "Stormwind flight master" },
