			written = { ["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Every Bloodsail drops Snuff and one of them carries Dizzy's eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the Wild Shore, south of Booty Bay.", ["The deserters camp south of the road, west of {npc:4503}'s hut."] = "The deserters camp south of the road, west of Mudcrush's hut.", ["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "Crank's next Zanzil errand starts in Thousand Needles: skip it.", ["{npc:2535} and {npc:2536}"] = "Maury and Jon-Jon", ["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "Roetten is in the Reclaimers' hall by the Hall of Explorers, Gerrig Bonegrip in the Forlorn Cavern.", ["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "Klannoc offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon.", ["{zone:1413}"] = "The Barrens" },
