 "Gregan Brewspewer", ["npc:7876"] = "Tran'rek", ["npc:7900"] = "Angelas Moonbreeze", ["npc:8496"] = "Liv Rizzlefix", ["npc:8596"] = "Plaguehound Runt", ["npc:8597"] = "Plaguehound", ["npc:8598"] = "Frenzied Plaguehound", ["npc:8600"] = "Plaguebat", ["npc:8603"] = "Carrion Grub", ["npc:8737"] = "Linken", ["npc:9117"] = "J.D. Collie", ["npc:9298"] = "Donova Snowden", ["npc:9299"] = "Gaeriyan", ["npc:9619"] = "Torwa Pathfinder", ["npc:9622"] = "U'cha", ["npc:9684"] = "Lar'korwi", ["npc:9997"] = "Spraggle Frock", ["npc:9999"] = "Ringo", ["object:175924"] = "Locked Cabinet", ["object:176370"] = "Boat to Auberdine", ["object:176498"] = "Portal to Darnassus", ["object:177667"] = "Torn Scroll", ["quest:1123"] = "Rabine Saturna", ["quest:2845"] = "Wandering Shay", ["quest:3444"] = "The Stone Circle", ["quest:5058"] = "Mrs. Dalson's Diary", ["quest:5154"] = "The Annals of Darrowshire", ["quest:5181"] = "Villains of Darrowshire", ["quest:5210"] = "Brother Carlin", ["quest:5401"] = "Argent Dawn Commission", ["quest:5537"] = "Skeletal Fragments", ["quest:5742"] = "Redemption", ["quest:6762"] = "Rabine Saturna", ["spell:437801"] = "Light's Hope", ["zone:1413"] = "The Barrens", ["zone:1422"] = "Western Plaguelands", ["zone:1423"] = "Eastern Plaguelands", ["zone:1425"] = "The Hinterlands", ["zone:1438"] = "Teldrassil", ["zone:1444"] = "Feralas", ["zone:1446"] = "Tanaris", ["zone:1448"] = "Felwood", ["zone:1449"] = "Un'Goro Crater", ["zone:1450"] = "Moonglade", ["zone:1451"] = "Silithus", ["zone:1452"] = "Winterspring", ["zone:1455"] = "Ironforge", ["zone:1457"] = "Darnassus" },
			written = { ["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "Back to Gregan's camp, just south-east of Rockbiter: the Evoroot buys three Videre Elixirs. Keep them: Donova takes one, and Gaeriyan in Gadgetzan shows himself only to someone who has drunk one.", ["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Cross the river east to the Undercroft, the crypt in the south-west of the zone. The Torn Scroll lies inside: its key is on Infiltrator Hameya in the far north-east, done in the next guide.", ["Cross the river west to {npc:1855}'s hut."] = "Cross the river west to Tirion's hut.", ["Cross the south of the crater to {npc:9619} by the ramp."] = "Cross the south of the crater to Torwa by the ramp.", ["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Fly from Gadgetzan to Marshal's Refuge. Linken stands at the back of the refuge; J.D. Collie is in the cave behind him.\nSpraggle's friend Ringo has gone missing.", ["From Theramore, ride west into the {zone:1413} and north up the coast to {area:392}."] = "From Theramore, ride west into the Barrens and north up the coast to Ratchet.", ["Lead {npc:7774} back to {npc:7765} at walking pace: she wanders off, so ring the bell to call her back (not in combat), and clear the harpies on the way before she reaches them."] = "Lead Shay back to Rockbiter at walking pace: she wanders off, so ring the bell to call her back (not in combat), and clear the harpies on the way before she reaches them.", ["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Ride east to the border river: Tirion lives in a small hut on the bank.", ["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Ride north to Terrordale. Augustus lives in the ruined hut, and his receipt book lies in the ruined inn nearby.", ["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Ride north up the road to the Northridge lumber mill; Kirsta hides at the camp's edge.", ["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "Ride west into the Ravenwind Ruins: Shay hides in the small round building at the back. Open the chest beside her for Shay's Bell: it lasts 15 minutes, like the quest.", ["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Take the boat to the mainland and ride north-east to Zorbin's camp by the Twin Colossals.", ["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "The cauldron sits at the Writhing Haunt, by Mulgris' farm.", ["The giant {npc:7765} sits just north-west of {npc:7775}'s camp."] = "The giant Rockbiter sits just north-west of Gregan's camp.", ["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "The tortured druids and sentinels haunt the ruined village south-west of Layo.", ["{area:202} cauldron"] = "Writhing Haunt cauldron", ["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "Davil's Libram lies in the town hall of Hearthglen, west of Tirion: the Scarlet guards stand close together.", ["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "Marlene's farmhouse stands on the hill east of the camp; Joseph Redpath's monument is just north of it.", ["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "Huntsman Radley walks the Northridge camp east of Kirsta; Cavalier Durgen guards the tower at Hearthglen's southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight.", ["{npc:7775}'s camp lies north of the {area:1119}. He brews the {item:11243} from an {item:11242}: take his errand for one."] = "Gregan's camp lies north of the Twin Colossals. He brews the Videre Elixir from an Evoroot: take his errand for one.", ["{npc:9619} camps at the foot of the ramp into the crater."] = "Torwa camps at the foot of the ramp into the crater.", ["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Lar'korwi's lair lies in the jungle north of Torwa, below the eastern cliffs: use Torwa's Pouch there. Lar'korwi is level 56: start at full health." },
