						{ t = "turnin", quest = 93791, title = "Speak with Belann", npc = 256507, npcName = "Belann Windwood", map = 2521, x = 62.89, y = 77.44, z = 668.5 },
						{ t = "accept", quest = 93797, title = "Boughs in the Wind", npc = 256507, npcName = "Belann Windwood", minLevel = 10, qlvl = 10, pre = { 93791 }, preTitles = { [93791] = "Speak with Belann" }, map = 2521, x = 62.89, y = 77.44, z = 668.5 },
					},
