-- Source: forever/class/paladin/tome-of-divinity.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/paladin/tome-of-divinity",
			pack = "guides",
			title = "{spell:7328} (Alliance)",
			faction = "Alliance",
			races = { "Human", "Dwarf" },
			classes = { "PALADIN" },
			minLevel = 12,
			maxLevel = 14,
			category = "Class",
			folder = "Paladin",
			keywords = { "The Tome of Divinity", "Tome of Divinity", "Redemption", "Symbol of Life", "Duthorian Rall", "Stephanie Turner", "Gazin Tenorm", "Henze Faulk", "Defias Script", "Tiza Battleforge", "John Turner", "Muiredon Battleforge", "Narm Faulk", "Dark Iron Script", "Brother Wilhelm", "Azar Stronghammer", "Brandur Ironhammer", "Linen Cloth", "Paladin", "class quest" },
			reward = { { spell = 7328, spellName = "Redemption" } },
			why = "{spell:7328} at 12, the paladin's resurrection: an easy chain through your capital and its home zone.",
			zone = 1453,
			zoneName = "Stormwind City",
			author = "Polestar",
			version = 1,
			names = { ["area:131"] = "Kharanos", ["area:212"] = "Helm's Bed Lake", ["area:56"] = "Heroes' Vigil", ["area:86"] = "Stone Cairn Lake", ["area:87"] = "Goldshire", ["item:2589"] = "Linen Cloth", ["item:6775"] = "Tome of Divinity", ["item:6846"] = "Defias Script", ["item:6847"] = "Dark Iron Script", ["item:6866"] = "Symbol of Life", ["item:6916"] = "Tome of Divinity", ["npc:1232"] = "Azar Stronghammer", ["npc:1245"] = "Kogan Forgestone", ["npc:1981"] = "Dark Iron Ambusher", ["npc:474"] = "Defias Rogue Wizard", ["npc:5149"] = "Brandur Ironhammer", ["npc:6171"] = "Duthorian Rall", ["npc:6172"] = "Henze Faulk", ["npc:6173"] = "Gazin Tenorm", ["npc:6174"] = "Stephanie Turner", ["npc:6175"] = "John Turner", ["npc:6177"] = "Narm Faulk", ["npc:6178"] = "Muiredon Battleforge", ["npc:6179"] = "Tiza Battleforge", ["npc:927"] = "Brother Wilhelm", ["npc:928"] = "Lord Grayson Shadowbreaker", ["object:147516"] = "Dark Iron", ["object:2096"] = "Trade District", ["object:32362"] = "Mystic Ward", ["object:32386"] = "Hall of Mysteries", ["quest:1641"] = "The Tome of Divinity", ["quest:1645"] = "The Tome of Divinity", ["spell:116"] = "Frostbolt", ["spell:7328"] = "Redemption", ["zone:1426"] = "Dun Morogh", ["zone:1432"] = "Loch Modan", ["zone:1436"] = "Westfall", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			written = { ["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "At 12 Brandur Ironhammer, the paladin trainer in Ironforge's Mystic Ward, sends you upstairs to Tiza Battleforge. The errand is optional, a little XP: Azar Stronghammer in Kharanos and Lord Grayson Shadowbreaker in Stormwind give the same one (taking one closes the others), and Tiza starts the chain without it.", ["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "At 12 Brother Wilhelm, the paladin trainer in Goldshire, sends you to Duthorian Rall in Stormwind's Cathedral of Light. The errand is optional, a little XP: Brandur Ironhammer in Ironforge gives the same one (taking one closes the other), and Duthorian starts the chain without it.", ["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "Back to the Cathedral of Light: Gazin takes the script, Duthorian teaches you Redemption.", ["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "Back to the Cathedral. Duthorian gives you the Symbol of Life; Gazin Tenorm lies wounded by the altar of the same hall. Keep the symbol: you need it on Henze Faulk. If you lose it, Duthorian gives you another (The Symbol of Life).", ["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "Back up to the Hall of Mysteries: Muiredon takes the script, Tiza teaches you Redemption.", ["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "Back upstairs in the Hall of Mysteries. Tiza gives you the Symbol of Life; her husband Muiredon Battleforge rests on the same floor. Keep the symbol: you need it on Narm Faulk. If you lose it, Tiza gives you another (The Symbol of Life).", ["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "The Defias Rogue Wizards around the big stone tablet east of Henze carry the Defias Script: about one kill in two drops it, but some players need many kills. They respawn in three minutes.", ["{npc:6171} stands inside the Cathedral of Light. He hands you the {item:6775}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6171} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "Duthorian Rall stands inside the Cathedral of Light. He hands you the Tome of Divinity: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask Duthorian for a new copy. Bring 10 Linen Cloth for the next step if you have it.", ["{npc:6179} stands upstairs in the {object:32386}, in the {object:32362}: take the ramp at the back of the hall. She hands you the {item:6916}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6179} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "Tiza Battleforge stands upstairs in the Hall of Mysteries, in the Mystic Ward: take the ramp at the back of the hall. She hands you the Tome of Divinity: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask Tiza for a new copy. Bring 10 Linen Cloth for the next step if you have it." },
			steps = {
				{
					title = "The summons (Human)",
					note = "At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it.",
					only = { races = { "Human" } },
					goals = {
						{ t = "level", level = 12 },
						{ t = "accept", quest = 2998, title = "Tome of Divinity", npc = 927, npcName = "Brother Wilhelm", minLevel = 12, qlvl = 12, closedBy = { 1642, 3681 }, preTitles = { [1642] = "The Tome of Divinity", [3681] = "Tome of Divinity" }, map = 1429, x = 41.1, y = 66.04, z = 57.7, f = "e", optional = true, note = "{npc:927}, {area:87}" },
					},
				},
				{
					title = "The summons (Dwarf)",
					note = "At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it.",
					only = { races = { "Dwarf" } },
					goals = {
