					note = "Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil.",
					goals = {
						{ t = "turnin", quest = 1654, title = "The Test of Righteousness", npc = 6181, npcName = "Jordan Stilwell", map = 1426, x = 52.49, y = 36.92, z = 495.3, f = "e" },
