-- Source: forever/class/warlock/felhunter-alliance.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/felhunter-alliance",
			pack = "guides",
			title = "Felhunter (Alliance)",
			faction = "Alliance",
			classes = { "WARLOCK" },
			minLevel = 30,
			maxLevel = 33,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Felhunter", "Tome of the Cabal", "Seeking Strahad", "Strahad Farsan", "Krom Stoutarm", "Moldy Tome", "Tattered Manuscript", "Damaged Chest", "Rod of Channeling", "Reconstructed Tome", "Dragonmaw Bonewarder", "Dragonmaw Shadowwarder", "Angerfang Encampment", "The Binding", "Box of Souls", "Warlock", "class pet" },
			reward = { { spell = 691, spellName = "Summon Felhunter" }, { item = 22244, itemName = "Box of Souls" } },
			why = "The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards.",
			zone = 1413,
			zoneName = "The Barrens",
			author = "Polestar",
			version = 1,
			names = { ["area:1036"] = "Angerfang Encampment", ["area:150"] = "Menethil Harbor", ["area:271"] = "Southshore", ["area:287"] = "Hillsbrad", ["area:35"] = "Booty Bay", ["area:392"] = "Ratchet", ["area:484"] = "Freewind Post", ["area:836"] = "Dun Algaz", ["item:22244"] = "Box of Souls", ["item:6931"] = "Moldy Tome", ["item:6997"] = "Tattered Manuscript", ["item:7006"] = "Reconstructed Tome", ["npc:6120"] = "Lago Blackwrench", ["npc:6122"] = "Gakin the Darkbinder", ["npc:6251"] = "Strahad Farsan", ["npc:6266"] = "Menara Voidrender", ["npc:6294"] = "Krom Stoutarm", ["object:2101"] = "Mage Quarter", ["object:2164"] = "Slaughtered Lamb", ["object:32356"] = "Hall of Explorers", ["object:32383"] = "Forlorn Cavern", ["object:92423"] = "Damaged Chest", ["quest:1758"] = "Tome of the Cabal", ["quest:1795"] = "The Binding", ["quest:1798"] = "Seeking Strahad", ["quest:1802"] = "Tome of the Cabal", ["quest:1804"] = "Tome of the Cabal", ["spell:691"] = "Summon Felhunter", ["zone:1413"] = "Barrens", ["zone:1441"] = "Thousand Needles", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			written = { ["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Back to Strahad in Ratchet. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the Tome of the Cabal on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon The Binding and take it again from Strahad. Keep the tome: Strahad takes it back.", ["Back to {npc:6294}"] = "Back to Krom", ["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "Krom pieces the tome together and gives you the Reconstructed Tome: keep it, Strahad takes it with the rods." },
			steps = {
				{
					title = "{quest:1798} ({zone:1453})",
