			folder = "Warlock",
			keywords = { "Summon Voidwalker", "Gakin's Summons", "The Slaughtered Lamb", "Surena Caledon", "The Binding", "Remen Marcot", "Lago Blackwrench", "Gakin the Darkbinder", "Surena's Choker", "Bloodstone Choker", "Morgan the Collector", "Brackwell Pumpkin Patch", "Summoning Circle", "Warlock", "class pet" },
			reward = { { spell = 697, spellName = "Summon Voidwalker" } },
			why = "Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt.",
			zone = 1429,
			zoneName = "Elwynn Forest",
			author = "Polestar",
			version = 1,
			names = { ["area:2257"] = "Deeprun Tram", ["area:62"] = "Brackwell Pumpkin Patch", ["area:87"] = "Goldshire", ["item:6928"] = "Bloodstone Choker", ["npc:473"] = "Morgan the Collector", ["npc:6120"] = "Lago Blackwrench", ["npc:6121"] = "Remen Marcot", ["npc:6122"] = "Gakin the Darkbinder", ["npc:881"] = "Surena Caledon", ["object:171524"] = "Tinker Town", ["object:2101"] = "Mage Quarter", ["object:32383"] = "Forlorn Cavern", ["quest:1685"] = "Gakin's Summons", ["quest:1689"] = "The Binding", ["quest:1715"] = "The Slaughtered Lamb", ["spell:14868"] = "Curse of Agony", ["spell:348"] = "Immolate", ["spell:697"] = "Summon Voidwalker", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			written = { ["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "At 10 Lago Blackwrench, the warlock trainer in Ironforge's Forlorn Cavern, sends you to Gakin the Darkbinder in Stormwind. Take the Deeprun Tram from Tinker Town. If Lago does not offer it, go to Gakin anyway: he still gives you the next quest.", ["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "Back to Gakin. He hands you the Bloodstone Choker. The circle is hard to find: take the stairs behind Gakin down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: Curse of Agony, Corruption and Immolate with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: Gakin takes it back.", ["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in Gakin's crypt.", ["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "Surena Caledon (level 9) is inside the farmhouse at the Brackwell Pumpkin Patch, south-east Elwynn near the Redridge road. Morgan the Collector (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on Surena first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop.", ["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "The Slaughtered Lamb is the tavern in the Mage Quarter; Gakin is in its cellar, down the stairs inside." },
			steps = {
				{
